// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        // Restrict _value to avoid overflow concerns; bound is optional
        _value = bound(_value, 0, address(c).balance);
        vm.assume(_target != address(0));

        // Call sendMoney on the contract
        c.sendMoney(_target, _value, _data);

        // General rule: after any sendMoney call, owner() must equal the deployer (this contract in test)
        assertTrue(c.owner() == address(this));
    }
}

